// Bind the English draft to the existing one-pass editor. No review model.
const rows=$input.all();
if(rows.length!==1)throw new Error('EN edit input: expected one draft');
const draft=rows[0].json.output;
if(typeof draft!=='string'||!draft.trim())throw new Error('EN edit input: draft is empty');
const context=$('Writer Invocation Gate').first().json;
if(!context?.content_id||context.writer_context?.config?.language!=='en-US'
 ||context.writer_brief?.schema!=='writer_brief.v3'||context.writer_brief.language!=='en-US')
 throw new Error('EN edit input: English writer context missing');
return [{json:{schema:'polish_input.v1',content_id:context.content_id,
 story_id:context.story_id,story_mode:context.story_mode,article_to_polish:draft,
 config:{...context.writer_context.config},writer_brief:context.writer_brief,
 writer_invocation_receipt:context.writer_invocation_receipt
},pairedItem:{item:0}}];

// Shape check only, not a factual or literary quality score. Keep the original on failure.
const input=$('V2 EN Edit Input').first().json,rows=$input.all();
if(rows.length!==1)throw new Error('EN preview: expected one edit');
const result=rows[0].json,draft=input.article_to_polish;
if(typeof draft!=='string'||!draft.trim())throw new Error('EN preview: original draft missing');
const candidate=typeof result.output==='string'?result.output:'';
const valid=!result.error&&candidate.trim().startsWith('# ')
 &&(candidate.match(/^#\s+\S.*$/gm)||[]).length===1
 &&candidate.trim().split('\n').slice(1).join('\n').trim().length>0;
const article=valid?candidate:draft;
return [{json:{schema:'writing_preview.v1',status:valid?'draft':'review_required',
 content_id:input.content_id,story_id:input.story_id,story_mode:input.story_mode,
 language:input.config.language,config:input.config,
 article_title:(article.match(/^#\s+(.+)$/m)||[,''])[1],
 article_markdown:article,draft_markdown:draft,editing_status:valid?'completed':'failed',
 warnings:valid?[]:[result.error?'editor_failed_original_retained':'invalid_edit_original_retained'],
 writer_invocation_receipt:input.writer_invocation_receipt,
 publication:{state:'NOT_PUBLISHED',url:null}
},pairedItem:{item:0}}];

// Terminal return: a failed edit keeps its original draft and never starts visuals.
const rows=$input.all(),p=rows[0]?.json;
if(rows.length!==1||p?.schema!=='writing_preview.v1'||p.status!=='review_required'
 ||p.editing_status!=='failed'||p.article_markdown!==p.draft_markdown
 ||p.publication?.state!=='NOT_PUBLISHED'||p.publication.url!==null)
 throw new Error('EN hold: expected a review-required unpublished preview');
return [{json:p,pairedItem:{item:0}}];
